import numpy as np
from collections import defaultdict
lines = open('optimized.xyz').read().split('\n')
n = int(lines[0])
els, xyz = [], []
for l in lines[2:2+n]:
    p = l.split()
    els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz = np.array(xyz)
cov = {'H':0.31,'C':0.76,'P':1.07,'S':1.05,'Tc':1.45}
bonds = defaultdict(list)
for i in range(n):
    for j in range(i+1,n):
        dd = np.linalg.norm(xyz[i]-xyz[j])
        if dd < cov[els[i]]+cov[els[j]]+0.45:
            bonds[i].append(j); bonds[j].append(i)
exp = {'Tc':6,'S':2,'P':4}
ok = True
for i,el in enumerate(els):
    nb = len(bonds[i])
    if el in exp and nb != exp[el]:
        ok=False; print("BAD", i, el, nb, bonds[i])
    if el=='C' and nb!=4: ok=False; print("BAD C", i, nb, bonds[i])
    if el=='H' and nb!=1: ok=False; print("BAD H", i, nb)
print("connectivity OK" if ok else "PROBLEMS")
# count H per carbon type
for i,el in enumerate(els):
    if el=='C':
        nh = sum(1 for j in bonds[i] if els[j]=='H')
        np_ = sum(1 for j in bonds[i] if els[j]=='P')
        ns = sum(1 for j in bonds[i] if els[j]=='S')
        nc = sum(1 for j in bonds[i] if els[j]=='C')
        print(i, f"H{nh} P{np_} S{ns} C{nc}")
EOF
